package com.sahseh.alarm
import android.app.*
import android.content.*
import android.os.Bundle
import android.view.Gravity
import android.widget.*
import androidx.appcompat.app.AppCompatActivity
import java.util.Calendar
class MainActivity: AppCompatActivity(){ override fun onCreate(savedInstanceState:Bundle?){ super.onCreate(savedInstanceState); val p=getSharedPreferences("sahseh",0); val root=LinearLayout(this).apply{orientation=1;gravity=Gravity.CENTER;setPadding(24,32,24,24);setBackgroundColor(0xFFF7F7FC.toInt())}; root.addView(TextView(this).apply{text="صحصح";textSize=34f;gravity=Gravity.CENTER}); root.addView(TextView(this).apply{text="منبّهك اللي ما بيستسلم 😴";textSize=17f;gravity=Gravity.CENTER}); val tp=TimePicker(this).apply{setIs24HourView(true)};root.addView(tp);val target=EditText(this).apply{hint="شو لازم تصوّر؟ (مثلاً: كوب)";setText(p.getString("target","cup"))};root.addView(target);root.addView(Button(this).apply{text="ضبط المنبّه";setOnClickListener{val word=target.text.toString().trim();if(word.isEmpty()){target.error="اكتب الشيء المطلوب";return@setOnClickListener};p.edit().putString("target",word).apply();val c=Calendar.getInstance().apply{set(Calendar.HOUR_OF_DAY,tp.hour);set(Calendar.MINUTE,tp.minute);set(Calendar.SECOND,0);if(timeInMillis<=System.currentTimeMillis())add(Calendar.DAY_OF_YEAR,1)};val a=getSystemService(ALARM_SERVICE) as AlarmManager;val pi=PendingIntent.getBroadcast(this@MainActivity,44,Intent(this@MainActivity,AlarmReceiver::class.java),PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE);try{if(android.os.Build.VERSION.SDK_INT>=31&&!a.canScheduleExactAlarms()){startActivity(Intent(android.provider.Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM))}else{a.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,c.timeInMillis,pi);Toast.makeText(this@MainActivity,"تم ضبط المنبّه",Toast.LENGTH_LONG).show()}}catch(e:Exception){Toast.makeText(this@MainActivity,"تعذّر ضبط المنبّه",Toast.LENGTH_LONG).show()}}},LinearLayout.LayoutParams(-1,56)) ; setContentView(root) }}